import{_ as a,c as t,o,a2 as c}from"./chunks/framework.mqLGQ42V.js";const b=JSON.parse('{"title":"舞台 (Stage) - Rive 编辑器","description":"舞台是一个无限的画布，你可以在其中放置包含所有图形的画板 (Artboards)。 只需点击即可选择一个对象，或者在多个形状上点击并拖动进行框选。按住 键可以在现有选区中添加或移除对象（通过单击或框选）。","frontmatter":{"title":"舞台 (Stage) - Rive 编辑器","description":"舞台是一个无限的画布，你可以在其中放置包含所有图形的画板 (Artboards)。 只需点击即可选择一个对象，或者在多个形状上点击并拖动进行框选。按住 键可以在现有选区中添加或移除对象（通过单击或框选）。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 界面面板, 舞台"}]]},"headers":[],"relativePath":"editor/interface-overview/stage.md","filePath":"editor/interface-overview/stage.md","lastUpdated":1774867914000}'),i={name:"editor/interface-overview/stage.md"};function n(r,e,d,l,s,h){return o(),t("div",null,[...e[0]||(e[0]=[c('<p>界面概览</p><h1 id="舞台-stage" tabindex="-1">舞台 (Stage) <a class="header-anchor" href="#舞台-stage" aria-label="Permalink to &quot;舞台 (Stage)&quot;">​</a></h1><p>舞台是一个无限的画布，你可以在其中放置包含所有图形的画板 (Artboards)。</p><h2 id="​-选择-selection" tabindex="-1"><a href="#selection">​</a> 选择 (Selection) <a class="header-anchor" href="#​-选择-selection" aria-label="Permalink to &quot;[​](#selection) 选择 (Selection)&quot;">​</a></h2><p>只需点击即可选择一个对象，或者在多个形状上点击并拖动进行框选。按住 <code>Shift</code> 键可以在现有选区中添加或移除对象（通过单击或框选）。</p><h3 id="​-双击-double-click" tabindex="-1"><a href="#double-click">​</a> 双击 (Double-click) <a class="header-anchor" href="#​-双击-double-click" aria-label="Permalink to &quot;[​](#double-click) 双击 (Double-click)&quot;">​</a></h3><p>要选择分组 (Group) 中的对象，请双击你想选择的对象。这会带你进入层级结构的下一层，并允许你选择该层级上的任何对象。</p><h3 id="​-深层选择-deep-select" tabindex="-1"><a href="#deep-select">​</a> 深层选择 (Deep select) <a class="header-anchor" href="#​-深层选择-deep-select" aria-label="Permalink to &quot;[​](#deep-select) 深层选择 (Deep select)&quot;">​</a></h3><p>为了选择分组内的对象，请按住 <code>⌘</code> (macOS) 或 <code>Ctrl</code> (Windows) 并直接点击该对象。这是一个穿透多层嵌套分组并直接选择形状的快速方法。这在导航复杂文件时非常快，尤其是结合下文描述的“选择底层 (Select behind)”技巧以及 Enter 和 Esc 快捷键使用时。</p><h3 id="​-选择底层-select-behind" tabindex="-1"><a href="#select-behind">​</a> 选择底层 (Select behind) <a class="header-anchor" href="#​-选择底层-select-behind" aria-label="Permalink to &quot;[​](#select-behind) 选择底层 (Select behind)&quot;">​</a></h3><p>当你将鼠标悬停在舞台上的某个对象上时，Rive 会在其周围绘制一个轮廓。这是一个提示，告诉你如果点击，该对象将被选中。有时多个对象会重叠在一起，难以准确选中你想要的那一个。在这种情况下，按住 <code>Alt</code> 键可在光标下的下一个对象之间循环。你可以持续按下 <code>Alt</code> 键，直到你想选择的对象被轮廓框出。此时点击即可选中它。</p><h3 id="​-enter-和-esc-快捷键" tabindex="-1"><a href="#enter-and-esc-shortcuts">​</a> Enter 和 Esc 快捷键 <a class="header-anchor" href="#​-enter-和-esc-快捷键" aria-label="Permalink to &quot;[​](#enter-and-esc-shortcuts) Enter 和 Esc 快捷键&quot;">​</a></h3><p>使用 <code>Enter</code> 键快速向下导航层级结构 (Hierarchy)。如果你选中了一个分组，这允许你快速选择其中的第一个子级。 使用 <code>Esc</code> 键快速向上导航层级结构。这允许你快速选择当前选中项的父级。</p><h2 id="​-导航-navigating" tabindex="-1"><a href="#navigating">​</a> 导航 (Navigating) <a class="header-anchor" href="#​-导航-navigating" aria-label="Permalink to &quot;[​](#navigating) 导航 (Navigating)&quot;">​</a></h2><h3 id="​-平移-panning" tabindex="-1"><a href="#panning">​</a> 平移 (Panning) <a class="header-anchor" href="#​-平移-panning" aria-label="Permalink to &quot;[​](#panning) 平移 (Panning)&quot;">​</a></h3><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 平移示例) 要平移舞台，请点击鼠标右键并拖动鼠标。如果你使用的是触控板，请左右滚动。此外，按住 <code>空格键 (Spacebar)</code> 可触发平移工具 (Pan Tool)。在启用平移工具的情况下，点击并拖动即可移动到舞台上你想要的位置。</p></blockquote><h3 id="​-缩放-zooming" tabindex="-1"><a href="#zooming">​</a> 缩放 (Zooming) <a class="header-anchor" href="#​-缩放-zooming" aria-label="Permalink to &quot;[​](#zooming) 缩放 (Zooming)&quot;">​</a></h3><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 缩放示例) 将光标置于舞台上方，按住 <code>⌘</code> / <code>Ctrl</code> 并滚动鼠标或触控板即可进行放大和缩小。此外，使用 <code>+</code> / <code>-</code> 键可在预设点之间缩放。你可以通过 <code>⌘</code> / <code>Ctrl</code> + <code>0</code> 快速恢复到 100%。</p></blockquote><h3 id="​-适应屏幕-fit" tabindex="-1"><a href="#fit">​</a> 适应屏幕 (Fit) <a class="header-anchor" href="#​-适应屏幕-fit" aria-label="Permalink to &quot;[​](#fit) 适应屏幕 (Fit)&quot;">​</a></h3><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 适应屏幕示例) 按下 <code>F</code> 键可同时缩放并调整活动画板的位置，使其填充可视图台区域。请注意，如果你在层级面板中选中了一个对象，此操作将针对该对象而非画板执行。 在某些情况下，你可能会在仍能看到层级结构的情况下“丢失”了画板。这通常发生在画板位置被意外设置了关键帧或缩放级别太远时。使用 <code>F</code> 快捷键将通过让选中对象或画板充满舞台来帮你解决此问题。</p></blockquote>',20)])])}const u=a(i,[["render",n]]);export{b as __pageData,u as default};
